import{_ as e,H as t,f as l,i as o}from"./chunks/framework.BH2BK_3i.js";const A=JSON.parse('{"title":"旅程再启｜共探AI与Golang新篇","description":"","frontmatter":{},"headers":[],"relativePath":"手把手带你写一个Web框架/旅程再启｜共探AI与Golang新篇.md","filePath":"手把手带你写一个Web框架/旅程再启｜共探AI与Golang新篇.md","lastUpdated":1779820017000}'),n={name:"手把手带你写一个Web框架/旅程再启｜共探AI与Golang新篇.md"};function _(i,a,r,p,s,d){return t(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="旅程再启-共探ai与golang新篇" tabindex="-1">旅程再启｜共探AI与Golang新篇 <a class="header-anchor" href="#旅程再启-共探ai与golang新篇" aria-label="Permalink to &quot;旅程再启｜共探AI与Golang新篇&quot;">​</a></h1><p>你好，我是轩脉刃。</p><p>我的专栏《手把手带你写一个 Web 框架》，自 2021 年底上线，至今已有三年多。在这段时间里，我一直在一线从事业务架构和实现工作。所负责的业务，是我十年职业生涯中遇到的并发量最大、容错率最低的，每天都有大量流量运行在我们编写的业务代码中。因此，我对如何编写规范的业务代码，以及如何更安全地进行业务开发有了更多思考和实践，特别是在高并发和大流量场景下。</p><p>同时，过去的三年也是 AI 爆发并逐渐改变传统编程范式的几年。在可预见的未来，AI 将对市场上程序员的技能需求产生显著影响。作为架构师，我们必须不断思考： <strong>如何改变以迎接 AI 的未来？需要掌握哪些技能才能符合未来的市场需求而不被淘汰？</strong></p><p>经过这三年的积累，我对职场、编程语言和 AI 领域有了更深入的理解，我也很乐意通过加餐的形式与你分享这些理解和想法。</p><p>总的来说，我将与你探讨以下几个话题（以实际上线为准）：</p><ul><li>AI 在 Golang 开发中能为我们带来哪些帮助？</li><li>Hade 框架新增了哪些新特性？</li><li>存储相关配置项的艺术</li><li>写好单元测试，让你的 Go 代码固若金汤</li></ul><p>如果你有更多想要了解的内容，欢迎在留言区告诉我！</p>',8)])])}const c=e(n,[["render",_]]);export{A as __pageData,c as default};
